"""
For this challenge, we know the values of A, g and p. But we don't know a and b.
a is generated by Alice and b is generated by Bob.

B = we supply the value of B equals to p, because that way s will become 0
s = pow(B, a, p)
key = s.to_bytes(256, "little")[:16]

cipher = AES.new(key=key, mode=AES.MODE_CBC)
flag = open("/flag", "rb").read()
ciphertext = cipher.iv + cipher.encrypt(pad(flag, cipher.block_size))
print(f"Flag Ciphertext (hex): {ciphertext.hex()}")

We don't know the AES key, the challenge is using to encrypt. So we will try to generate
s, such that AES key becomes predictable and we can use our own code to decrypt.

"""

import secrets
from Crypto.Cipher import AES
from Crypto.Util.Padding import unpad

p_hex = ""

a_hex = ""

g_hex = "0x2"

p = int(p_hex, 16)
g = int(g_hex, 16)
A = int(a_hex, 16)

b = secrets.randbelow(p - 2) + 1

B = pow(g, b, p)
s = 0

print("B:", format(B, "x"))
print("shared secret:", format(s, "x"))

aes_key = s.to_bytes(256, "little")[:16]

ct = bytes.fromhex(input("Cipher text hex? "))
aes_key = bytes.fromhex(aes_key.hex())

iv = ct[:16]
ciphertext = ct[16:]

cipher = AES.new(aes_key, AES.MODE_CBC, iv)
pt = unpad(cipher.decrypt(ciphertext), AES.block_size)
print("Message:", pt.decode("ascii"))
